// ── يُضاف إلى Program.cs قبل app.Run() ──────────────────────────
if (!app.Environment.IsDevelopment())
{
    app.UseHsts();                      // HSTS: إجبار HTTPS في المتصفح
    app.UseHttpsRedirection();
}

app.UseSecurityHeaders();               // CSP · X-Content-Type-Options · Referrer-Policy

// حد معدل على نقاط حساسة — يمنع التعداد والتخمين
app.UseRateLimiter();

app.MapPost("/bff/login", LoginHandler.Handle)
   .RequireRateLimiting("auth");        // مثال: 10 محاولات/دقيقة لكل IP

app.MapHealthChecks("/alive", new() { Predicate = r => r.Name == "self" });
app.MapHealthChecks("/health");         // يشمل القاعدة

// بيانات تجريبية فقط — لا PII حقيقية
if (app.Configuration.GetValue<bool>("Seed:Enabled"))
    await DemoSeed.RunAsync(app.Services);

app.Run();

// appsettings.Production.json — بلا أسرار:
// { "Seed": { "Enabled": true }, "Logging": { "LogLevel": { "Default": "Warning" } } }
// الأسرار تأتي من متغيرات بيئة (secretref) أو Key Vault.
